export const chargeOptions = CHARGES.map((charge) => charge.name)

export const CHARGES_BY_CATEGORY = CHARGES.reduce((acc, charge) => {
  if (!acc[charge.category]) acc[charge.category] = []
  acc[charge.category].push(charge)
  return acc
}, {})

export const arrestChargeCatalog = Object.fromEntries(
  CHARGES.map((charge) => [charge.name, { fine: charge.fine, jail: charge.jail, label: charge.name }])
)
